(* [comment removed for export] *)
Definition gl3_exit (ra sp gp tp t1 t2 t3 t4 t5 t6 s0 s1 s3 s7 s9 s10 s11 a4 a5 a6 a7 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (t0' s2' s4' s5' s6' s8' a0' a1' a2' a3' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0' t1 t2 s0 s1 a0' a1' a2' a3' a4 a5 a6 a7 s2' s3 s4' s5' s6' s7 s8' s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xbe6d8) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma gl3_rows : forall (k : nat) (i : Z)
    (ra gp tp a1 a2 a4 a5 s0 s4 s5 s8 s9 s10 s11 t5 w88 w96 : word) F fc (m : mem)
    (FP dh swpl dwpl PS3 PD3 SR sn DR dn fl sh rsh : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 ->
  0 < swpl <= 2^24 -> 0 < dwpl <= 2^24 -> swpl * dh <= 2^24 -> dwpl * dh <= 2^24 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PS3 mod 4 = 0 -> PD3 mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  0 < FP -> FP mod 16 = 0 -> FP + 256 <= 2^47 -> (DR + dn <= FP \/ FP + 256 <= DR) ->
  0 <= fl < 2 -> 0 <= sh < 32 -> 0 <= rsh < 32 ->
  (forall i', 0 <= i' <= dh -> SR <= PS3 + 4 * (swpl * i') /\ PS3 + 4 * (swpl * i') + 4 <= SR + sn + 4 * swpl) ->
  (fl = 0 -> forall i', 0 <= i' < dh -> PS3 + 4 * (swpl * i') + 8 <= SR + sn) ->
  (forall i', 0 <= i' < dh -> SR <= PS3 + 4 * (swpl * i') /\ PS3 + 4 * (swpl * i') + 4 <= SR + sn) ->
  (forall i', 0 <= i' < dh -> DR <= PD3 + 4 * (dwpl * i') /\ PD3 + 4 * (dwpl * i') + 4 <= DR + dn) ->
  rw_cells asegs m (FP + 88) [C8 w88; C8 w96; C8 (Z_to_bv 64 PS3)] ->
  rw_cells asegs m (FP + 120) [C8 (Z_to_bv 64 0); C8 (Z_to_bv 64 0)] ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (gl3_exit ra (Z_to_bv 64 FP) gp tp (Z_to_bv 64 2147450880) (Z_to_bv 64 (swpl * 4)) (Z_to_bv 64 (-5)) (Z_to_bv 64 (PS3 + swpl * 4)) t5
               (Z_to_bv 64 sh) s0 (Z_to_bv 64 rsh) (Z_to_bv 64 (dwpl * 4)) (Z_to_bv 64 31) s9 s10 s11 a4 a5 (Z_to_bv 64 0) (Z_to_bv 64 32) F fc m DR dn)
    (MS (mkR ra (Z_to_bv 64 FP) gp tp (Z_to_bv 64 fl) (Z_to_bv 64 2147450880) (Z_to_bv 64 (swpl * 4)) s0 (Z_to_bv 64 rsh)
             (Z_to_bv 64 (PD3 + 4 * (dwpl * i))) a1 a2 (Z_to_bv 64 (4 * (swpl * i))) a4 a5 (Z_to_bv 64 0) (Z_to_bv 64 32)
             (Z_to_bv 64 (PD3 + 4 * (dwpl * i))) (Z_to_bv 64 (dwpl * 4)) s4 s5 (Z_to_bv 64 (i - dh)) (Z_to_bv 64 31) s8 s9 s10 s11
             (Z_to_bv 64 (-5)) (Z_to_bv 64 (PS3 + swpl * 4)) t5 (Z_to_bv 64 sh))
        F (Z_to_bv 64 0xbe404) fc None m (seg_rom asegs)).
Proof.
