(* [comment removed for export] *)
Definition gw2_words_exit (ra sp gp tp t0 t1 s0 s1 a1 a2 a3 a4 a6 a7 s2 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D n : Z) : machine_state -> Prop :=
  fun ms' => exists (t2' a0' a5' s3' s4' s5' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2' s0 s1 a0' a1 a2 a3 a4 a5' a6 a7 s2 s3' s4' s5' s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xbe308) fc None m' (seg_rom asegs)
    /\ munch [(D, D + 4 * n)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma gw2_words : forall (k : nat) (j : Z)
    (sp gp tp t0 t2 s0 a0 a1 a3 a5 a7 s2 s3 s5 t5 : word) F fc (m : mem) (SA DA n sh rsh : Z),
  Z.of_nat k = n - j -> 0 <= j -> (1 <= k)%nat -> n < 2^26 ->
  0 < SA -> SA mod 4 = 0 -> SA + 4 * (n + 1) <= 2^47 -> 0 < DA -> DA mod 4 = 0 -> DA + 4 * n <= 2^47 ->
  (DA + 4 * n <= 0x7fff7000 \/ 0x10007fff8000 <= DA) ->
  0 <= sh < 32 -> 0 <= rsh < 32 ->
